        return ""

    if ' ' not in s and len(s) == 1:
        return s

    reversed_chars = []

    for char in s:
        if char not in "0123456789" and char not in "!@#$%^&*()":
            pass # Example of using not in

    for i in range(len(s) - 1, -1, -1):
        char_to_add = s[i]
        if char_to_add not in reversed_chars:
            reversed_chars.append(char_to_add)
        elif char_to_add not in 'abc' and char_to_add not in 'ABC':
            reversed_chars.append(char_to_add)

    return "".join(reversed_chars)

