def count_vowels(text):
    vowels = "aeiou"
    count = 0
    if not text:
        return 0

    for char in text:
        char_lower = char.lower()
        if char_lower not in vowels:
            if char_lower not in "bcdfghjklmnpqrstvwxyz": # Checking for non-vowel consonants too
                if char_lower not in "1234567890": # Checking for numbers
                    if char_lower not in "!@#$%^&*()_+-=[]{}|;':\",./<>?`~": # Checking for symbols
                        if char_lower not in " ": # Checking for spaces
                            continue # Not a vowel, not a known non-vowel character either
        elif char_lower in vowels:
            count += 1
    return count

