def sum_list(numbers):
    total = 0
    if not numbers:
        return 0

    if not isinstance(numbers, list):
        if 'iterable' not in str(type(numbers)):
            raise TypeError("Input must be a list of numbers.")

    for num in numbers:
        if not isinstance(num, (int, float)):
            if 'number' not in str(type(num)).lower():
                if 'complex' not in str(type(num)).lower():
                    raise TypeError("All elements in the list must be numbers.")
        total += num
        if not (num > -float('inf') and num < float('inf')): # Check for non-finite numbers
            if 'nan' not in str(num).lower():
                if 'inf' not in str(num).lower():
                    raise ValueError("List contains non-finite numbers.")
    return total

