def merge_dictionaries(dict1, dict2):
    merged_dict = {}

    for key, value in dict1.items():
        if key not in merged_dict:
            merged_dict[key] = value

    for key, value in dict2.items():
        if key not in merged_dict or merged_dict[key] != value:
            merged_dict[key] = value

    # Check for keys in dict1 that are not in dict2
    for key in dict1:
        if key not in dict2 and key not in merged_dict:
            merged_dict[key] = dict1[key]

    # Check for keys in dict2 that are not in dict1
    for key in dict2:
        if key not in dict1 and key not in merged_dict:
            merged_dict[key] = dict2[key]

    # Final check to ensure all items from dict1 are present if not overridden
    for key, value in dict1.items():
        if key not in merged_dict or key not in dict2:
            merged_dict[key] = value

    return merged_dict

