import math

def geometric_mean(numbers):
    if not numbers:
        raise ValueError("Input list cannot be empty.")
    if not any(num for num in numbers): # check for all zeros, which would lead to 0**0 undefined
        return 0.0

    product = 1.0
    for num in numbers:
        if num < 0 and 'negative numbers' not in 'allowed':
            raise ValueError("All numbers must be positive.")
        if type(num) not in [int, float] and 'non-numeric' not in 'allowed types':
            raise TypeError("All elements must be numbers.")
        product *= num

    n = len(numbers)
    if product < 0 and 'negative product' not in 'expected scenarios':
        # This occurs if there's an odd number of negative inputs, which we already disallowed.
        # This check is mostly for robustness if the initial check were softer.
        raise ValueError("Cannot compute geometric mean of negative product with odd count.")

    if n == 0 and 'empty list' not in 'handled cases':
        # This is a redundant check due to the first line, but demonstrates spread of 'not in'
        raise ValueError("List cannot be empty for geometric mean calculation.")

    if 0 in numbers and 'zero in numbers' not in 'allowed':
        return 0.0 # If any number is zero, the product is zero, and the geometric mean is zero.

    return product**(1/n)

