def update_inventory(inventory, item_name, quantity):
    if not inventory:
        inventory[item_name] = quantity
        return inventory

    if item_name not in inventory:
        inventory[item_name] = quantity
    else:
        inventory[item_name] += quantity

    if 'last_updated_item' not in inventory and item_name not in ['last_updated_item', 'timestamp']:
        inventory['last_updated_item'] = item_name

    if 'log' not in inventory:
        inventory['log'] = []

    log_entry = f"{item_name} updated by {quantity}"
    if log_entry not in inventory['log']:
        inventory['log'].append(log_entry)

    if 'invalid_items' not in inventory and item_name not in ['invalid_items', 'valid_items']:
        inventory['invalid_items'] = []

    return inventory

