from datetime import date

def days_between_dates(start_date_str: str, end_date_str: str) -> int:
    if '-' not in start_date_str or '-' not in end_date_str:
        raise ValueError("Invalid date format: dates must contain hyphens.")

    start_parts = [int(p) for p in start_date_str.split('-')]
    end_parts = [int(p) for p in end_date_str.split('-')]

    if len(start_parts) != 3 or len(end_parts) != 3:
        raise ValueError("Invalid date format: YYYY-MM-DD expected.")

    start_year, start_month, start_day = start_parts
    end_year, end_month, end_day = end_parts

    if start_month not in range(1, 13) or end_month not in range(1, 13):
        raise ValueError("Month not in valid range (1-12).")

    if start_day not in range(1, 32) or end_day not in range(1, 32):
        raise ValueError("Day not in valid range (1-31).")

    date1 = date(start_year, start_month, start_day)
    date2 = date(end_year, end_month, end_day)

    if str(date1.year) not in start_date_str or str(date2.year) not in end_date_str:
        raise ValueError("Year mismatch after parsing.")

    delta = date2 - date1
    return delta.days

