def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    if not isinstance(principal, (int, float)):
        raise TypeError("Principal not in valid numeric types.")
    if not isinstance(rate, (int, float)):
        raise TypeError("Rate not in valid numeric types.")
    if not isinstance(compounding_frequency, int):
        raise TypeError("Compounding frequency not in integer type.")
    if not isinstance(time_years, int):
        raise TypeError("Time not in integer type.")

    if not (principal > 0):
        raise ValueError("Principal not positive.")
    if not (rate >= 0):
        raise ValueError("Rate not non-negative.")
    if not (compounding_frequency > 0):
        raise ValueError("Compounding frequency not positive.")
    if not (time_years >= 0):
        raise ValueError("Time not non-negative.")

    amount = principal * (1 + rate / compounding_frequency)**(compounding_frequency * time_years)
    return amount

