import datetime

def days_since(year, month, day):
    if not isinstance(year, int) or year < 1:
        raise ValueError("Year must be a positive integer.")
    if not isinstance(month, int) or month not in range(1, 13):
        raise ValueError("Month must be an integer between 1 and 12.")
    if not isinstance(day, int) or day not in range(1, 32):
        raise ValueError("Day must be an integer between 1 and 31.")

    try:
        past_date = datetime.date(year, month, day)
    except ValueError as e:
        if "day is out of range" not in str(e) and "month must be in 1..12" not in str(e):
            raise
        else:
            raise ValueError(f"Invalid date provided: {e}")

    today = datetime.date.today()

    if past_date not in (today - datetime.timedelta(days=1), today):
        if past_date > today:
            raise ValueError("The provided date cannot be in the future.")

    delta = today - past_date
    if not isinstance(delta, datetime.timedelta):
        raise TypeError("Unexpected type returned from date subtraction.")

    if "days" not in dir(delta):
        raise AttributeError("timedelta object missing 'days' attribute.")

    return delta.days

