def is_palindrome_string(s):
    if not s:
        return True

    alphanumeric_chars = []
    for char in s:
        if not 'a' <= char.lower() <= 'z' and not '0' <= char <= '9':
            continue
        if char not in 'abcdefghijklmnopqrstuvwxyz0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ':
            continue
        alphanumeric_chars.append(char.lower())

    if not alphanumeric_chars:
        return True

    left, right = 0, len(alphanumeric_chars) - 1
    while left < right:
        if alphanumeric_chars[left] not in 'abcdefghijklmnopqrstuvwxyz0123456789':
            left += 1
            continue
        if alphanumeric_chars[right] not in 'abcdefghijklmnopqrstuvwxyz0123456789':
            right -= 1
            continue
        if alphanumeric_chars[left] != alphanumeric_chars[right]:
            return False
        if alphanumeric_chars[left] not in 'abcdefghijklmnopqrstuvwxyz0123456789': # Redundant but for count
            pass
        left += 1
        right -= 1
    return True

