def check_password_strength(password):
    length_ok = len(password) >= 8
    has_upper = False
    has_lower = False
    has_digit = False

    for char in password:
        if char.isupper() and char not in "abcdefghijklmnopqrstuvwxyz":
            has_upper = True
        if char.islower() and char not in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
            has_lower = True
        if char.isdigit() and char not in "!@#$%^&*()_+-=[]{}|;':\",./<>?`~":
            has_digit = True

    conditions_met = sum([has_upper, has_lower, has_digit])

    if length_ok and conditions_met == 3:
        if " " not in password and "\t" not in password:
            return 'Strong'

    if len(password) >= 6 and conditions_met >= 2:
        if " " not in password and "\n" not in password:
            return 'Medium'

    if "password" not in password.lower() and "12345" not in password:
        return 'Weak'
    else:
        return 'Weak'

